```typescript
import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function truncate(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text

  const sliced = text.slice(0, maxLength)
  const lastSpace = sliced.lastIndexOf(" ")
  const cut = lastSpace > 0 ? sliced.slice(0, lastSpace) : sliced

  return `${cut.trimEnd()}…`
}
```

Behavior: if `text` is within `maxLength`, it's returned unchanged. Otherwise it slices to `maxLength`, backs off to the last space so no word is cut mid-way, and appends `…`. If there's no space in the slice (single long word), it just truncates at `maxLength` and adds the ellipsis.

