```typescript
export function formatRelativeTime(date: Date | string): string {
  const target = typeof date === "string" ? new Date(date) : date;
  const seconds = Math.round((target.getTime() - Date.now()) / 1000);
  const absSeconds = Math.abs(seconds);

  const units: { limit: number; divisor: number; unit: Intl.RelativeTimeFormatUnit }[] = [
    { limit: 60, divisor: 1, unit: "second" },
    { limit: 3600, divisor: 60, unit: "minute" },
    { limit: 86400, divisor: 3600, unit: "hour" },
    { limit: 604800, divisor: 86400, unit: "day" },
    { limit: 2629800, divisor: 604800, unit: "week" },
    { limit: 31557600, divisor: 2629800, unit: "month" },
    { limit: Infinity, divisor: 31557600, unit: "year" },
  ];

  if (absSeconds < 5) return "just now";

  const rtf = new Intl.RelativeTimeFormat("en", { numeric: "auto" });
  const { divisor, unit } = units.find(({ limit }) => absSeconds < limit)!;
  const value = Math.round(seconds / divisor);

  return rtf.format(value, unit);
}
```

Uses the built-in `Intl.RelativeTimeFormat`, so no extra dependency. Handles both past ("3 days ago") and future ("in 2 hours") dates, and accepts either a `Date` or an ISO string.

